(4415194, 635535, 17279, '<td valign="top">I''m guessing the "six" string is the connection to the challenge... it''s a bit tenuous in my eyes, but otherwise a nice image.</td>', 'I''m guessing the "six" string is the connection to the challenge... it''s a bit tenuous in my eyes, but otherwise a nice image.', '2008-01-22 21:49:10.000000', NULL, 1),
(4415203, 636048, 17279, '<td valign="top">To me, the selective desaturation doesn''t really work here especially with the selective blurring (or sharpening).  It does scream "six" though! :)</td>', 'To me, the selective desaturation doesn''t really work here especially with the selective blurring (or sharpening).  It does scream "six" though! :)', '2008-01-22 21:50:46.000000', NULL, 1),
(4415210, 635871, 17279, '<td valign="top">I think that this image would be greatly improved with a change in lighting.  The current lighting looks a bit harsh in places and overall seems to leave the subject flat.</td>', 'I think that this image would be greatly improved with a change in lighting.  The current lighting looks a bit harsh in places and overall seems to leave the subject flat.', '2008-01-22 21:52:03.000000', NULL, 1),
(4415223, 633491, 17279, '<td valign="top">The DPC printout quality is very poor... I think it really makes this imaage suffer.  The other things I don''t get: why is there one red die and is there any significance to the 5s showing on 4 of the dice and the 2 showing on the others?</td>', 'The DPC printout quality is very poor... I think it really makes this imaage suffer.  The other things I don''t get: why is there one red die and is there any significance to the 5s showing on 4 of the dice and the 2 showing on the others?', '2008-01-22 21:54:56.000000', NULL, 1),
(4415227, 635835, 17279, '<td valign="top">This is a rather interesting image... is this a model?  I think it looks rather cool, but in my mind, it really doesn''t meet the challenge.</td>', 'This is a rather interesting image... is this a model?  I think it looks rather cool, but in my mind, it really doesn''t meet the challenge.', '2008-01-22 21:55:45.000000', NULL, 1),
(4415311, 636145, 73250, '<td valign="top">I like this portrait...excellent color with the eyes and the expression is priceless. I think he needs a little more color in his cheeks though.<br/><br/><i>Message edited by author 2008-02-07 17:46:22.</i></td>', 'I like this portrait...excellent color with the eyes and the expression is priceless. I think he needs a little more color in his cheeks though.', '2008-01-22 22:14:57.000000', '2008-02-07 17:46:22.000000', 1),
(4415324, 635604, 17279, '<td valign="top">Well captured with nice DOF.  I like the BW treatment as well.  There is a tenuous connection to the challenge topic though.</td>', 'Well captured with nice DOF.  I like the BW treatment as well.  There is a tenuous connection to the challenge topic though.', '2008-01-22 22:19:09.000000', NULL, 1),
(4415325, 634788, 17279, '<td valign="top">Nice image, but a real stretch to meet the challenge (at least to me).</td>', 'Nice image, but a real stretch to meet the challenge (at least to me).', '2008-01-22 22:19:17.000000', NULL, 1),
(4415326, 635809, 17279, '<td valign="top">I''m having trouble understanding how the die fits in with the jar, marbles and shadow.</td>', 'I''m having trouble understanding how the die fits in with the jar, marbles and shadow.', '2008-01-22 22:19:21.000000', NULL, 1),
(4415327, 635605, 17279, '<td valign="top">An interesting concept.  My biggest problem with this image (a big one for me because it is so glaring) is that the wrench is being used incorrectly.</td>', 'An interesting concept.  My biggest problem with this image (a big one for me because it is so glaring) is that the wrench is being used incorrectly.', '2008-01-22 22:19:24.000000', NULL, 1),
(4415328, 636038, 17279, '<td valign="top">Nice image.  Doesn''t really say "six" to me.  The difference in color of the first apple from the others is also a bit distracting.</td>', 'Nice image.  Doesn''t really say "six" to me.  The difference in color of the first apple from the others is also a bit distracting.', '2008-01-22 22:19:30.000000', NULL, 1),
(4415333, 636012, 17279, '<td valign="top">The lighing on this is poor and the subject blends in with the distracting background.  I like the idea of the pressure guage, but I think you should have cropped in tightly on that.  The rest of the image is more a distraction than a benefit.</td>', 'The lighing on this is poor and the subject blends in with the distracting background.  I like the idea of the pressure guage, but I think you should have cropped in tightly on that.  The rest of the image is more a distraction than a benefit.', '2008-01-22 22:21:20.000000', NULL, 1),
(4415334, 636061, 17279, '<td valign="top">Sorry, bit to me, this image is uninteresting (I can''t even tell what it is) and has a tenuous connection to the topic (there could be 7 mounds in the image).</td>', 'Sorry, bit to me, this image is uninteresting (I can''t even tell what it is) and has a tenuous connection to the topic (there could be 7 mounds in the image).', '2008-01-22 22:21:25.000000', NULL, 1),
(4415336, 636066, 17279, '<td valign="top">Interesting idea.  I think it would have fared better with different lighting.</td>', 'Interesting idea.  I think it would have fared better with different lighting.', '2008-01-22 22:22:39.000000', NULL, 1),
(4415338, 635920, 17279, '<td valign="top">Nice image and colors.  I like the lighing on this.</td>', 'Nice image and colors.  I like the lighing on this.', '2008-01-22 22:23:41.000000', NULL, 1),
(4415341, 636143, 17279, '<td valign="top">Sexy image, but I think it''s a bit of a stretch for the challenge topic.  It really doesn''t convey "six".  I really had to look a bit to get it.</td>', 'Sexy image, but I think it''s a bit of a stretch for the challenge topic.  It really doesn''t convey "six".  I really had to look a bit to get it.', '2008-01-22 22:23:48.000000', NULL, 1),
(4415347, 635006, 17279, '<td valign="top">Interesting wideable shot.  I like the B/W.  I don''t know if it would have been possible to have all of the name showing on all the labels, but it would have added to this image I think.</td>', 'Interesting wideable shot.  I like the B/W.  I don''t know if it would have been possible to have all of the name showing on all the labels, but it would have added to this image I think.', '2008-01-22 22:25:04.000000', NULL, 1),
(4415362, 636160, 17279, '<td valign="top">The six in this image isn''t as prominent as I would like it to be to really meet the challenge theme.</td>', 'The six in this image isn''t as prominent as I would like it to be to really meet the challenge theme.', '2008-01-22 22:28:01.000000', NULL, 1),
(4415366, 635865, 17279, '<td valign="top">Interesting image... I would love to see this cropped tighter so as to get a better feel for their expressions.  Also it seem a bit blurry or OOF.</td>', 'Interesting image... I would love to see this cropped tighter so as to get a better feel for their expressions.  Also it seem a bit blurry or OOF.', '2008-01-22 22:28:56.000000', NULL, 1),
(4415371, 635169, 17279, '<td valign="top">naughty, naughty :)</td>', 'naughty, naughty :)', '2008-01-22 22:29:50.000000', NULL, 1),
(4415500, 635835, 36371, '<td valign="top">I love this shot! Very nice detail. And to answer your question: I choose the 3rd from the right OR the 4th from the left (whichever way ya look at it....)</td>', 'I love this shot! Very nice detail. And to answer your question: I choose the 3rd from the right OR the 4th from the left (whichever way ya look at it....)', '2008-01-22 22:58:56.000000', NULL, 1),
(4415595, 635668, 17279, '<td valign="top">Clever</td>', 'Clever', '2008-01-22 23:22:01.000000', NULL, 1),
(4415598, 635223, 17279, '<td valign="top">Very nicely executed.  DOF really makes the dice stand out!</td>', 'Very nicely executed.  DOF really makes the dice stand out!', '2008-01-22 23:22:45.000000', NULL, 1),
(4415602, 634945, 17279, '<td valign="top">Wonderful landscape and excellent colors.  I have a slight problem witht he fact that there are actually more than six palm in the photo.</td>', 'Wonderful landscape and excellent colors.  I have a slight problem witht he fact that there are actually more than six palm in the photo.', '2008-01-22 23:23:35.000000', NULL, 1),
(4415604, 636062, 17279, '<td valign="top">Excellent idea and nicely executed.  Why didn''t you use six dice though to emphasize the concept of 6???  Also, I don''t care so much for the clear die... I think he colors work much better.</td>', 'Excellent idea and nicely executed.  Why didn''t you use six dice though to emphasize the concept of 6???  Also, I don''t care so much for the clear die... I think he colors work much better.', '2008-01-22 23:24:59.000000', NULL, 1),
(4415607, 635155, 17279, '<td valign="top">It doesn''t really scream "six" to me, but I think this is really cool!  This would make a great print if you clone out the cables!</td>', 'It doesn''t really scream "six" to me, but I think this is really cool!  This would make a great print if you clone out the cables!', '2008-01-22 23:26:17.000000', NULL, 1),
(4415610, 636210, 17279, '<td valign="top">excellent execution on this theme that I have seen before (no points deducted for that).  I would have liked to see all of the yellow ducks in focus though.</td>', 'excellent execution on this theme that I have seen before (no points deducted for that).  I would have liked to see all of the yellow ducks in focus though.', '2008-01-22 23:27:38.000000', NULL, 1),
(4415612, 636225, 17279, '<td valign="top">Nice take on the challenge.  While not a great image overall, it is one that meets the theme better than most I think.  7</td>', 'Nice take on the challenge.  While not a great image overall, it is one that meets the theme better than most I think.  7', '2008-01-22 23:28:42.000000', NULL, 1),
(4415613, 635471, 17279, '<td valign="top">Extra points for a beautiful image.  It really screams "Corona" more than "six" LOL.  This would do really well in an advertising challenge I think.</td>', 'Extra points for a beautiful image.  It really screams "Corona" more than "six" LOL.  This would do really well in an advertising challenge I think.', '2008-01-22 23:30:04.000000', NULL, 1),
(4415620, 635122, 17279, '<td valign="top">Clean and simple.  Using three nuts (total of six in the image with reflections) might meet the challenge better, but the resulting image would not be as pleasant.  Also I am somewhat distracted by the double edges on the reflections.</td>', 'Clean and simple.  Using three nuts (total of six in the image with reflections) might meet the challenge better, but the resulting image would not be as pleasant.  Also I am somewhat distracted by the double edges on the reflections.', '2008-01-22 23:32:15.000000', NULL, 1),
(4415623, 635924, 17279, '<td valign="top">Very creative.  I love the lighting and textures on this image.</td>', 'Very creative.  I love the lighting and textures on this image.', '2008-01-22 23:33:10.000000', NULL, 1),
(4415628, 635113, 17279, '<td valign="top">Great colors and composition.  I am not sure the "six" is so apparent here, but overall a really nice image.</td>', 'Great colors and composition.  I am not sure the "six" is so apparent here, but overall a really nice image.', '2008-01-22 23:34:06.000000', NULL, 1),
(4415633, 636087, 17279, '<td valign="top">I really like the lighting and texture on this.  The only thing that kind of bugs me is the clock hand at the top.  Either it should be cropped out altogether or it should be in the image pointing at the 6.</td>', 'I really like the lighting and texture on this.  The only thing that kind of bugs me is the clock hand at the top.  Either it should be cropped out altogether or it should be in the image pointing at the 6.', '2008-01-22 23:35:25.000000', NULL, 1),
(4415636, 634828, 17279, '<td valign="top">Great idea and take on this challenge.</td>', 'Great idea and take on this challenge.', '2008-01-22 23:36:04.000000', NULL, 1),
(4415637, 636013, 17279, '<td valign="top">Great idea and well executed.</td>', 'Great idea and well executed.', '2008-01-22 23:36:25.000000', NULL, 1),
(4415644, 635671, 17279, '<td valign="top">This is very well done... Using the roman numeral for 6 was a stroke of genius (maybe angle the one flower down a little more).  One of my favorites in this challenge. 10</td>', 'This is very well done... Using the roman numeral for 6 was a stroke of genius (maybe angle the one flower down a little more).  One of my favorites in this challenge. 10', '2008-01-22 23:38:38.000000', NULL, 1),
(4415648, 636104, 17279, '<td valign="top">I like this... great perspective!</td>', 'I like this... great perspective!', '2008-01-22 23:39:52.000000', NULL, 1),
(4415649, 634201, 17279, '<td valign="top">Nice image.  I thought it was a bit of a stretch in meeting the challenge at first, but after looking at it more, it became more obvious.  Bumping up.</td>', 'Nice image.  I thought it was a bit of a stretch in meeting the challenge at first, but after looking at it more, it became more obvious.  Bumping up.', '2008-01-22 23:39:59.000000', NULL, 1),
(4415654, 635820, 17279, '<td valign="top">Beautiful colors and composition.</td>', 'Beautiful colors and composition.', '2008-01-22 23:41:10.000000', NULL, 1),
(4415674, 634815, 17279, '<td valign="top">Nice colors and DOF.  I would like to see a bit tighter crop and all the berries in focus.</td>', 'Nice colors and DOF.  I would like to see a bit tighter crop and all the berries in focus.', '2008-01-22 23:45:04.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4415682, 635968, 17279, '<td valign="top">Nicely done.  The selective desat takes away from this image, at least for me.</td>', 'Nicely done.  The selective desat takes away from this image, at least for me.', '2008-01-22 23:46:16.000000', NULL, 1),
(4415693, 636166, 17279, '<td valign="top">Nice use of negative space, but really needs something to make it pop I think.  If the moon appeared larger perhaps?</td>', 'Nice use of negative space, but really needs something to make it pop I think.  If the moon appeared larger perhaps?', '2008-01-22 23:48:38.000000', NULL, 1),
