(4430041, 632931, 1031, '<td valign="top">Luckily, I think it probably took me less time to find it than it did you -- nice idea and find. Muted colors work well.</td>', 'Luckily, I think it probably took me less time to find it than it did you -- nice idea and find. Muted colors work well.', '2008-01-27 20:46:16.000000', NULL, 1),
(4430049, 636079, 50674, '<td valign="top">Best one yet :) Fantastic work, hope it does well</td>', 'Best one yet :) Fantastic work, hope it does well', '2008-01-27 20:48:22.000000', NULL, 1),
(4430052, 635535, 1031, '<td valign="top">Another subject I considered but never got around to shooting for this challenge :-)<br/> <br/>Post-processing suits the subject and mood well.</td>', 'Another subject I considered but never got around to shooting for this challenge :-) Post-processing suits the subject and mood well.', '2008-01-27 20:48:44.000000', NULL, 1),
(4430080, 635437, 1031, '<td valign="top">With your current cropping I can''t tell if that''s the <b>F7</b> key next to the <b>F5</b> ... ;-)</td>', 'With your current cropping I can''t tell if that''s the F7 key next to the F5 ... ;-)', '2008-01-27 20:55:20.000000', NULL, 1),
(4430086, 635499, 1031, '<td valign="top">If you are interested in doing a photographic series, doing something similar to these in all the arrangements in a set of dominoes seems like it might work.</td>', 'If you are interested in doing a photographic series, doing something similar to these in all the arrangements in a set of dominoes seems like it might work.', '2008-01-27 20:57:47.000000', NULL, 1),
(4430090, 636210, 1031, '<td valign="top">Isn''t that the one which will become a swan? ;-)</td>', 'Isn''t that the one which will become a swan? ;-)', '2008-01-27 20:58:41.000000', NULL, 1),
(4430099, 634966, 1031, '<td valign="top">Probably not ones I''d eat though, at least from an initial assessment ... :-(</td>', 'Probably not ones I''d eat though, at least from an initial assessment ... :-(', '2008-01-27 21:02:20.000000', NULL, 1),
(4430103, 635751, 1031, '<td valign="top">Nice blend of still and moving objects.</td>', 'Nice blend of still and moving objects.', '2008-01-27 21:03:36.000000', NULL, 1),
