(4430308, 635491, 81301, '<td valign="top">awesome! the best i have seen on this challenge... 10</td>', 'awesome! the best i have seen on this challenge... 10', '2008-01-27 21:59:22.000000', NULL, 1),
(4430339, 636104, 83416, '<td valign="top">I hope you were not standing in front of that fire engine speeding to the rescue :D  great capture!</td>', 'I hope you were not standing in front of that fire engine speeding to the rescue :D  great capture!', '2008-01-27 22:10:04.000000', NULL, 1),
(4430341, 635702, 67697, '<td valign="top">My favorite part about this photo is the senitiment behind it.  It''s also funny with the poor dog looking in and the silhouetted cat looking out.  Nice use of light and shadow here.</td>', 'My favorite part about this photo is the senitiment behind it.  It''s also funny with the poor dog looking in and the silhouetted cat looking out.  Nice use of light and shadow here.', '2008-01-27 22:10:40.000000', NULL, 1),
(4430343, 635825, 87328, '<td valign="top">The water seems over edited, nice other than that.</td>', 'The water seems over edited, nice other than that.', '2008-01-27 22:10:54.000000', NULL, 1),
(4430346, 636038, 67697, '<td valign="top">I love this photo for some reason and there''s no easy reason to pinpoint why.  I do love the greens but I think the way it just kind of slowly shrinks into the background is what I like the most.</td>', 'I love this photo for some reason and there''s no easy reason to pinpoint why.  I do love the greens but I think the way it just kind of slowly shrinks into the background is what I like the most.', '2008-01-27 22:11:38.000000', NULL, 1),
(4430347, 635665, 67697, '<td valign="top">I love the simplicity and the stark black and white contrasts.</td>', 'I love the simplicity and the stark black and white contrasts.', '2008-01-27 22:12:08.000000', NULL, 1),
(4430353, 635154, 67697, '<td valign="top">This is such a fun find!  I love all the difference faces here.  Beautiful captures of textures as well.  I also wonder how this would look in black and white?</td>', 'This is such a fun find!  I love all the difference faces here.  Beautiful captures of textures as well.  I also wonder how this would look in black and white?', '2008-01-27 22:12:54.000000', NULL, 1),
(4430355, 632931, 67697, '<td valign="top">Did you arrange it this way or did you just happen upon it?  I love how the 6 blends in with the scene and does not look out of place.</td>', 'Did you arrange it this way or did you just happen upon it?  I love how the 6 blends in with the scene and does not look out of place.', '2008-01-27 22:13:42.000000', NULL, 1),
(4430359, 634828, 67697, '<td valign="top">Very pretty.  Love the silhouette.  The simplicity makes this beautiful.</td>', 'Very pretty.  Love the silhouette.  The simplicity makes this beautiful.', '2008-01-27 22:14:16.000000', NULL, 1),
(4430365, 636079, 67697, '<td valign="top">This is truly one heck of an amazing macro shot.  I love the use of the white background to make all the different colors stand out.</td>', 'This is truly one heck of an amazing macro shot.  I love the use of the white background to make all the different colors stand out.', '2008-01-27 22:15:22.000000', NULL, 1),
(4430369, 636002, 83416, '<td valign="top">Simply love this shot  somehow reminds of a Western movie. Great!</td>', 'Simply love this shot  somehow reminds of a Western movie. Great!', '2008-01-27 22:16:05.000000', NULL, 1),
(4430371, 636064, 67697, '<td valign="top">This is so cute.  I love the one looking up.  This would make a great birthday card! (maybe without the ribbon lol)</td>', 'This is so cute.  I love the one looking up.  This would make a great birthday card! (maybe without the ribbon lol)', '2008-01-27 22:16:26.000000', NULL, 1),
(4430381, 636104, 67697, '<td valign="top">What great timing!  Love the perspective.  The lighting in the background looks good too.</td>', 'What great timing!  Love the perspective.  The lighting in the background looks good too.', '2008-01-27 22:18:32.000000', NULL, 1),
(4430387, 636156, 83416, '<td valign="top">... and a great image!</td>', '... and a great image!', '2008-01-27 22:19:24.000000', NULL, 1),
(4430396, 636233, 67697, '<td valign="top">Who knew chicks were born with pens? hehe  Very cute idea.</td>', 'Who knew chicks were born with pens? hehe  Very cute idea.', '2008-01-27 22:20:33.000000', NULL, 1),
(4430402, 635961, 67697, '<td valign="top">Very pretty.  I love the green contrast against the white background.  Nice job capturing the detail of the snow.</td>', 'Very pretty.  I love the green contrast against the white background.  Nice job capturing the detail of the snow.', '2008-01-27 22:21:27.000000', NULL, 1),
(4430409, 634602, 67697, '<td valign="top">This is a fun catch.  I like your timing with the balloon in the air and then seeing the logo on the truck.  The only thing is that without the title, I would not have been able to make a connection to 6.  Good luck!</td>', 'This is a fun catch.  I like your timing with the balloon in the air and then seeing the logo on the truck.  The only thing is that without the title, I would not have been able to make a connection to 6.  Good luck!', '2008-01-27 22:23:13.000000', NULL, 1),
(4430424, 635122, 67697, '<td valign="top">I love the blue but I cannot tell if you did a little too much oversaturation of it?  The shadows look blue to me.  Also, the reflections are slightly blurred like either from camera shake or someone hit the camera right at the wrong moment.  Very interesting setup tho - I love the progression of larger to smaller nut.</td>', 'I love the blue but I cannot tell if you did a little too much oversaturation of it?  The shadows look blue to me.  Also, the reflections are slightly blurred like either from camera shake or someone hit the camera right at the wrong moment.  Very interesting setup tho - I love the progression of larger to smaller nut.', '2008-01-27 22:26:18.000000', NULL, 1),
(4430435, 636038, 80859, '<td valign="top">nice photo.  i like the attention to detail (alternating the direction of the stems).   well-framed and lit and such /8</td>', 'nice photo.  i like the attention to detail (alternating the direction of the stems).   well-framed and lit and such /8', '2008-01-27 22:29:15.000000', NULL, 1),
(4430709, 633934, 80859, '<td valign="top">that water is so clear.  it looks as if their floating in the air.  tre cool</td>', 'that water is so clear.  it looks as if their floating in the air.  tre cool', '2008-01-27 23:55:19.000000', NULL, 1),
